/* @lc app=leetcode id=3187 lang=kotlin */ class Solution { fun pk(a: IntArray, i: Int) = i in 1..a.size - 2 && a[i - 1] < a[i] && a[i] > a[i + 1] fun badd(t: IntArray, i: Int, d: Int) = generateSequence(i + 1) { it + (it and -it) }.takeWhile { it < t.size }.forEach { t[it] += d } fun bq(t: IntArray, i: Int): Int = generateSequence(i) { it - (it and -it) }.takeWhile { it > 0 }.sumOf { t[it] } fun countOfPeaks(nums: IntArray, queries: Array<IntArray>): List<Int> = nums.copyOf().let { a -> IntArray(a.size + 1).let { t -> a.indices.filter { pk(a, it) }.forEach { badd(t, it, 1) }.let { queries.mapNotNull { q -> if (q[0] == 1) (if (q[1] + 1 > q[2] - 1) 0 else bq(t, q[2]) - bq(t, q[1] + 1)) else (q[1] - 1..q[1] + 1).filter { it in 1..a.size - 2 }.let { idxs -> idxs.map { pk(a, it) }.let { before -> a.set(q[1], q[2]).let { idxs.forEachIndexed { k, i -> pk(a, i).let { after -> if (after != before[k]) badd(t, i, if (after) 1 else -1) } } } } }.let { null } } } } } }